-- Devy — Hyprland entry point (Hyprland >= 0.57, Lua config).
-- ~/.config/hypr is a symlink to this folder in the Devy repo.
--
-- Load order (later files win):
--   1. modules/*            Devy defaults (in git)
--   2. devy/current/hypr    the active theme, generated by `devy-theme`
--   3. devy/local/gpu       machine-specific GPU/VM settings, generated by install.sh
--   4. devy/user            YOUR overrides — never touched by Devy updates
--
-- Every require() is its own protected scope: an error in one file pops a
-- notification but does not stop the others from loading.

local home = os.getenv("HOME")
local devy = home .. "/.config/devy"

require("modules/env")
require("modules/monitors")
require("modules/input")
require("modules/looknfeel")
require("modules/binds")
require("modules/rules")
require("modules/autostart")

-- Optional files: only required when they exist, so a missing file is not an error.
-- (Absolute paths with ".lua" are accepted by Hyprland's require, see wiki: configuring/core.)
local function optional(path)
  local f = io.open(path, "r")
  if f then
    f:close()
    require(path)
  end
end

optional(devy .. "/current/hypr.lua")
optional(devy .. "/local/gpu.lua")
optional(devy .. "/user.lua")
